            .andExpect(status().isNotFound());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerSuccess() throws Exception {
        String body = """
            {"firstName":"Wolfgang","lastName":"Steinbeck","address":"42 Nowhere Rd.","city":"Madison","telephone":"6085551099"}
